import { homedir } from "node:os";
import { join } from "node:path";
import mkcert from "vite-plugin-mkcert";

/**
 * Two build modes, picked by STORYBLOK_VERSION:
 * - "published" (production): every story is pre-rendered to flat HTML at build time. No bridge.
 * - "draft" (Visual Editor preview): a client-rendered SPA that fetches drafts live and loads the bridge.
 */
const version = process.env.STORYBLOK_VERSION === "draft" ? "draft" : "published";
const isDraft = version === "draft";
const isDev = process.argv.includes("dev");

/** Certs generated by vite-plugin-mkcert, signed by the locally trusted mkcert CA. */
const mkcertDir = join(homedir(), ".vite-plugin-mkcert");

/** Story folders that hold data for other pages rather than pages of their own. */
const dataFolders = ["record/"];

async function storyRoutes(): Promise<string[]> {
  const token = process.env.STORYBLOK_DELIVERY_API_TOKEN;
  if (!token) return ["/"];
  const routes = new Set<string>(["/"]);
  for (let page = 1; ; page++) {
    const res = await fetch(
      `https://api.storyblok.com/v2/cdn/links?token=${token}&version=${version}&per_page=1000&page=${page}&cv=${Date.now()}`,
    );
    if (!res.ok) throw new Error(`Storyblok links request failed: ${res.status}`);
    const { links } = (await res.json()) as {
      links: Record<string, { slug: string; is_folder: boolean; is_startpage: boolean }>;
    };
    const items = Object.values(links);
    for (const link of items) {
      if (link.is_folder || dataFolders.some((f) => link.slug.startsWith(f))) continue;
      const slug = link.is_startpage ? link.slug.replace(/\/?[^/]*$/, "") : link.slug;
      routes.add(slug === "home" || slug === "" ? "/" : `/${slug}`);
    }
    if (items.length < 1000) break;
  }
  return [...routes];
}

export default defineNuxtConfig({
  compatibilityDate: "2026-01-13",
  devtools: { enabled: false },
  modules: ["@storyblok/nuxt"],
  css: ["~/assets/css/main.css"],

  ssr: !isDraft,

  storyblok: {
    accessToken: process.env.STORYBLOK_DELIVERY_API_TOKEN,
    bridge: isDraft || isDev,
    apiOptions: {
      region: (process.env.STORYBLOK_REGION || "eu").toLowerCase(),
    },
  },

  runtimeConfig: {
    public: {
      sbVersion: isDev ? "draft" : version,
      siteUrl: process.env.SITE_URL || "https://martinalcock.co.uk",
    },
  },

  app: {
    head: {
      htmlAttrs: { lang: "en-GB" },
      link: [
        { rel: "preconnect", href: "https://fonts.googleapis.com" },
        { rel: "preconnect", href: "https://fonts.gstatic.com", crossorigin: "" },
        {
          rel: "stylesheet",
          href: "https://fonts.googleapis.com/css2?family=Anybody:wdth,wght@50..150,400..900&family=Golos+Text:wght@400;500;600&family=IBM+Plex+Mono:wght@400;500&display=swap",
        },
        { rel: "icon", type: "image/svg+xml", href: "/favicon.svg" },
      ],
      meta: [{ name: "theme-color", content: "#ECEAE4" }],
    },
  },

  hooks: {
    async "nitro:config"(nitro) {
      if (isDraft || isDev) return;
      nitro.prerender ||= {};
      nitro.prerender.routes = [...(nitro.prerender.routes || []), ...(await storyRoutes())];
      nitro.prerender.crawlLinks = true;
      // Hosted experiments are static files in public/x, not Storyblok routes.
      nitro.prerender.ignore = [...(nitro.prerender.ignore || []), "/x/"];
      nitro.prerender.failOnError = true;
    },
  },

  devServer: isDev
    ? {
        https: {
          key: join(mkcertDir, "dev.pem"),
          cert: join(mkcertDir, "cert.pem"),
        },
      }
    : {},

  vite: {
    plugins: isDev ? [mkcert()] : [],
  },
});
